SET disabled_optimizers='projection_placement';
CREATE TABLE placement_dim AS SELECT i::INTEGER AS i, (i % 10)::INTEGER AS k, lpad(i::VARCHAR, 50, 'x') AS v FROM range(20) t(i);
CREATE TABLE placement_dim2 AS SELECT i::INTEGER AS i, (i % 5)::INTEGER AS grp, ('tag_' || i)::VARCHAR AS tag FROM range(20) t(i);
CREATE TABLE placement_fact AS SELECT (i % 20)::INTEGER AS i, (i % 7)::INTEGER AS f_val, i::INTEGER AS id FROM range(200) t(i);
CREATE TABLE placement_fact2 AS SELECT (i % 20)::INTEGER AS i, (i % 9)::INTEGER AS score, i::INTEGER AS id FROM range(100) t(i);
ANALYZE;
SELECT s.*, lag(s, 1) OVER (ORDER BY f_val) FROM (SELECT d.s, f.f_val, row_number() OVER (PARTITION BY d.i ORDER BY f.f_val) AS rn FROM (SELECT i, substring(v, -9, 5) AS s FROM placement_dim) d INNER JOIN placement_fact f USING (i) WHERE f.f_val > 1) s ORDER BY ALL;

SET delim_join_as_cte=false;
CREATE TABLE placement_dim AS SELECT i::INTEGER AS i, (i % 10)::INTEGER AS k, lpad(i::VARCHAR, 50, 'x') AS v FROM range(20) t(i);
CREATE TABLE placement_dim2 AS SELECT i::INTEGER AS i, (i % 5)::INTEGER AS grp, ('tag_' || i)::VARCHAR AS tag FROM range(20) t(i);
CREATE TABLE placement_fact AS SELECT (i % 20)::INTEGER AS i, (i % 7)::INTEGER AS f_val, i::INTEGER AS id FROM range(200) t(i);
CREATE TABLE placement_fact2 AS SELECT (i % 20)::INTEGER AS i, (i % 9)::INTEGER AS score, i::INTEGER AS id FROM range(100) t(i);
ANALYZE;
SELECT * FROM (SELECT d.s, f.f_val, row_number() OVER (PARTITION BY d.i ORDER BY f.f_val) AS rn FROM (SELECT i, substring(v, -5, 16) AS s FROM placement_dim) d LEFT JOIN placement_fact f USING (i) WHERE f.f_val > 3 LIMIT 10) s1 UNION ALL SELECT * FROM (SELECT d.s, f.f_val, row_number() OVER (PARTITION BY d.i ORDER BY f.f_val) AS rn FROM (SELECT i, substring(v, -5, 16) AS s FROM placement_dim) d LEFT JOIN placement_fact f USING (i) WHERE f.f_val > 3 LIMIT 10) s2 ORDER BY ALL;
